{"cards": [{"node_code": "N_9095046f6d8faef9", "definition": "研究人体生理、心理特征与机械系统交互的工效学设计，涵盖人体尺寸适配、操作姿态、认知负荷管理及作业环境舒适性，旨在提升人机系统的效率、健康与可用性。", "boundary": "聚焦于“人”的因素在机械设计中的具体应用。包括基于人体测量学的空间布局、控制元件的人因设计、信息呈现的认知工效及物理环境（噪声、振动、热）对操作者的影响。区别于纯安全防护，本节点侧重操作体验与生理/心理负荷优化；纯心理学理论或纯医学研究不作为主挂载，除非直接指导工效设计。", "includes": ["基于人体尺寸、姿态与可达性的空间与布局设计", "认知负荷、信息呈现与控制布局的人因设计", "作业环境（噪声、振动、热）对操作者舒适性与可用性的影响及对策"], "excludes": ["纯人体生理学或心理学基础理论研究（除非直接应用于工效学设计）", "纯安全防护装置设计（如联锁、护罩），应归入机械安全与防护设计"], "sibling_distinctions": [{"other_code": "N_0629e6e5f163f717", "rule": "本节点侧重操作舒适性、效率及生理/心理负荷优化（如减少疲劳），安全节点侧重防止伤害（如防止夹伤）；若设计既影响舒适又涉及安全，侧重操作体验归本节点，侧重伤害预防归安全节点。"}, {"other_code": "N_b8cb1e9a0b8ba5ff", "rule": "本节点侧重功能操作的人因适配（如按钮位置、视野），形态节点侧重外观视觉语义与美学；涉及操作界面时，本节点关注操作便捷性，形态节点关注界面视觉风格。"}], "cross_boundary_rule": "涉及控制布局时，若侧重物理空间与人因归本节点，侧重控制逻辑归控制节点；涉及产品外观时，若侧重结构强度归设计/优化节点，侧重视觉语义归形态节点。"}, {"node_code": "N_0629e6e5f163f717", "definition": "研究机械系统中危险源的识别、本质安全设计、防护装置及联锁机制，旨在通过设计手段消除或控制风险，防止人员伤害及设备损坏，确保机械在正常及可预见误用下的安全性。", "boundary": "聚焦于机械系统的安全防护设计与风险控制。包括危险源辨识、本质安全（如消除危险能量）、物理防护（护罩、联锁）、安全距离及应急停止设计。区别于工效设计，本节点核心目标是“防伤害”而非“提效率”；纯法律条文解读或纯事故统计分析不作为主挂载，除非直接指导安全设计。", "includes": ["危险源识别、风险评估与本质安全设计原则", "防护装置、联锁机构、安全距离及急停装置设计", "误用、可预见使用及紧急情况下的安全设计与应急机制"], "excludes": ["纯操作舒适性或效率优化设计（如减少疲劳），应归入人机工效设计", "纯法律合规性审查或纯事故统计研究，应归入设计评价与合规性"], "sibling_distinctions": [{"other_code": "N_9095046f6d8faef9", "rule": "本节点侧重防止伤害（如防止夹伤、触电），工效节点侧重操作舒适与效率（如减少疲劳）；若设计既影响舒适又涉及安全，侧重伤害预防归本节点，侧重操作体验归工效节点。"}, {"other_code": "N_0ecba5f55dc118d5", "rule": "本节点侧重安全机制的设计实现（如联锁结构），评价节点侧重安全标准的符合性验证与认证；涉及安全时，本节点关注“如何设计得安全”，评价节点关注“是否满足安全标准”。"}], "cross_boundary_rule": "涉及控制布局时，若侧重物理空间与人因归工效节点，侧重控制逻辑归控制节点；涉及产品外观时，若侧重结构强度归设计/优化节点，侧重视觉语义归形态节点。"}, {"node_code": "N_0ecba5f55dc118d5", "definition": "研究机械产品的设计评价方法、原型测试、用户试验及标准符合性认证，涵盖技术、经济、环境多维评价，确保设计满足功能、安全、成本及法规要求，实现设计确认与合规上市。", "boundary": "聚焦于设计过程的验证、确认及合规性管理。包括设计评审、原型测试、用户可用性测试、全生命周期成本/环境评价及国际标准（如ISO、CE）符合性认证。区别于具体设计方法，本节点侧重“评价”与“合规”；纯法律条文解读或纯市场营销策略不作为主挂载，除非涉及设计合规性。", "includes": ["技术、经济与环境多维设计评价方法", "原型制作、用户试验、可用性测试与设计确认流程", "国际标准符合性、设计认证及法规合规性管理"], "excludes": ["纯安全防护装置设计（如联锁、护罩），应归入机械安全与防护设计", "纯操作舒适性或效率优化设计（如减少疲劳），应归入人机工效设计"], "sibling_distinctions": [{"other_code": "N_0629e6e5f163f717", "rule": "本节点侧重安全标准的符合性验证与认证，安全节点侧重安全机制的设计实现；涉及安全时，本节点关注“是否满足安全标准”，安全节点关注“如何设计得安全”。"}, {"other_code": "N_9095046f6d8faef9", "rule": "本节点侧重设计评价方法与合规性，工效节点侧重工效指标的设计实现；涉及可用性时，本节点关注评价流程与标准，工效节点关注具体的人因设计策略。"}], "cross_boundary_rule": "涉及控制布局时，若侧重物理空间与人因归工效节点，侧重控制逻辑归控制节点；涉及产品外观时，若侧重结构强度归设计/优化节点，侧重视觉语义归形态节点。"}]}
